import { PASSWORD, USERS, expect, expectStatus, test } from "../../fixtures";

test("sign-in ignores the case of the email address", { tag: "@LIF-11" }, async ({ request }) => {
  // Arrange: the seeded member's address with mixed case in the local part and domain
  const [local, domain] = USERS.member.split("@");
  const mixedCaseEmail = `${local[0].toUpperCase()}${local.slice(1)}@${domain.toUpperCase()}`;

  // Act
  const response = await request.post("/api/auth/login", {
    data: { email: mixedCaseEmail, password: PASSWORD },
  });

  // Assert: sign-in succeeds and the current user's email is lowercased
  const body = await expectStatus<{ access_token: string; user: { email: string } }>(response, 200);
  expect(body.user.email).toBe(USERS.member);

  // Assert the stored outcome, not only the login echo
  const me = await expectStatus<{ email: string }>(
    await request.get("/api/me", { headers: { Authorization: `Bearer ${body.access_token}` } }),
    200,
  );
  expect(me.email).toBe(USERS.member);
});
